export const LENGTH_UNITS=["px","cm","mm","in","pc","pt","ch","em","rem","vh","vw","vmin","vmax"];export const CSSLengthRegex=new RegExp(`(?<value>[+-]?\\d*\\.?\\d+)(?<unit>${LENGTH_UNITS.join("|")})`);export const parseText=e=>{const t=e.match(CSSLengthRegex);return t&&t.groups?{value:Number(t.groups.value),unit:t.groups.unit}:null};